code_anchors.code:
task automatic axi_write32(
    input  logic [15:0] addr,
    input  logic [31:0] data,
    input  logic [3:0]  wstrb,
    output logic [1:0]  bresp
);
    @(posedge clk);
    s_axi_awaddr  <= addr;
    s_axi_awvalid <= 1'b1;
    wait (s_axi_awready && s_axi_wready);
    @(posedge clk);
    s_axi_awvalid <= 1'b0;
    wait (s_axi_bvalid);
    bresp = s_axi_bresp;
endtask

typedef enum logic [2:0] {
    RX_IDLE, RX_START, RX_DATA, RX_PARITY, RX_STOP
} rx_state_e;

task automatic uart_drive_rx_byte(
    input byte data,
    input int  baud_div
);
    uart_rx <= 1'b1;
    repeat (baud_div) @(posedge clk);
    uart_rx <= 1'b0; // start bit
    repeat (baud_div) @(posedge clk);
    for (int i = 0; i < 8; i++) begin
        uart_rx <= data[i];
        repeat (baud_div) @(posedge clk);
    end
    uart_rx <= 1'b1; // stop bit
endtask

if (rx_state == RX_START && os_tick) begin
    if (sample_cnt == OVERSAMPLE/2) begin
        if (uart_rx == 1'b0) begin
            rx_state_n = RX_DATA;
            bit_idx_n  = '0;
        end else begin
            rx_state_n = RX_IDLE;
        end
    end
end

if (!rst_n) begin
    ctrl_reg   <= '0;
    irq_status <= '0;
    uart_tx    <= 1'b1;
end

if (wr_fire && wr_addr == TXDATA_ADDR && !tx_full) begin
    tx_fifo_push  <= 1'b1;
    tx_fifo_wdata <= wdata[7:0];
end

if (rx_frame_done) begin
    if (!rx_full) begin
        rx_fifo_push  <= 1'b1;
        rx_fifo_wdata <= rx_shift_reg;
    end else begin
        rx_overrun <= 1'b1;
    end
end

if (wr_fire && wr_addr == BAUD_ADDR) begin
    baud_div <= wdata[15:0];
end

task automatic axi_read32(
    input  logic [15:0] addr,
    output logic [31:0] data,
    output logic [1:0]  rresp
);
    @(posedge clk);
    s_axi_araddr  <= addr;
    s_axi_arvalid <= 1'b1;
    wait (s_axi_arready);
    wait (s_axi_rvalid);
    data  = s_axi_rdata;
    rresp = s_axi_rresp;
endtask

assert property (@(posedge clk) disable iff (!rst_n)
    (ctrl_rx_irq_en && !rx_empty) |-> irq
);

always_comb begin
    ctrl_reg_n = ctrl_reg;
    baud_div_n = baud_div;
    bresp_n = 2'b00;
    if (wr_fire) begin
        unique case (wr_addr)
            CTRL_ADDR: ctrl_reg_n = wdata;
            BAUD_ADDR: baud_div_n = wdata[15:0];
            default:   bresp_n = 2'b10;
        endcase
    end
end
